import React, { useEffect, useRef, useState } from 'react';
import { Badge, Col, Row, Spinner } from 'react-bootstrap';
// import ModelViewBox from '../../components/Atom/ModelViewBox';
// import FormLayout from '../../utils/formLayout';
// import { formContainer } from './formFieldData';
import Table from '../../components/Table';
import {
    calculateTotalInterestPayable,
    capitalizeFirstLetter,
    DateMonthYear,
    emiCalculation,
    findArrObj,
    findDueDate,
    findLastDate,
    formatDate,
    numberWithCommas,
    objectToKeyValueArray,
    percentageVal,
    showConfirmationDialog,
    showConfirmationDisbursed,
    showMessage,
    TableWithForm,
} from '../../utils/AllFunction';
import {
    updateIncomeEntryRequest,
    createAddLoanRequest,
    resetCreateAddLoan,
    getAddLoanRequest,
    resetGetAddLoan,
    resetUpdateAddLoan,
    updateAddLoanRequest,
    resetGetAddLoanDetails,
    // getContraRequest,
    // resetGetContra,
} from '../../redux/actions';
import { usePageTitle, useRedux } from '../../hooks';
import { NotificationContainer } from 'react-notifications';
import { disbursedDateFormContainer, districtFormContainer, callcelledFormContainer, cashHistoryFormContainer } from './formData';
import _ from 'lodash';
import { useLocation, useNavigate } from 'react-router-dom';
import FormLayout from '../../utils/formLayout';
import ModelViewBox from '../../components/Atom/ModelViewBox';
import CompanyDetails from '../../components/Atom/CompanyDetails';
import moment from 'moment';
import noProfile from '../../assets/images/noprofile_images.jpg';
import { baseURL } from '../../api/ApiConfig';
// import { cashHistoryFormCon tainer } from '../borrower-loan-list/formData';

let StatusName = 'Update';
const today = new Date().toISOString().split('T')[0];
function Index() {

    const location = useLocation();
    const { loanData, isCreated } = location.state || false;
    const checkPathName = () => {
        const pathName = location.pathname.split('/')[2];
        switch (pathName) {
            case 'request':
                return "Request";
            case 'approved':
                return "Approved";
            case 'disbursed':
                return "Disbursed";
            case 'cancelled':
                return "Cancelled";
            default:
                return ''
        }
    }
    const { dispatch, appSelector } = useRedux();
    const loginInfo = localStorage.getItem('loginInfo');
    const localData = JSON.parse(loginInfo);
    const pageAccessData = findArrObj(localData?.[0]?.pagePermission, 'label', checkPathName());
    const accessIds = (pageAccessData?.[0]?.access || '').split(',').map(id => id.trim()); // for access create and update and delete actions ['1', '2', '3', '4', '5', '6']
    const branchIdforRole = localData?.[0]?.branchId; // for branch list can only show
    const roleIdforRole = localData?.[0]?.roleId; // for role Permission (1.superadmin)

    usePageTitle({
        title: 'Loan',
        breadCrumbItems: [
            {
                path: '/loan/addloan',
                label: 'Loan',
            },
            {
                path: '/loan/addloan',
                label: 'Loan List',
                active: true,
            },
        ],
    });

    const navigate = useNavigate();

    const {
        // create loan
        createAddLoanSuccess,
        createAddLoanFailure,
        // update loan
        updateAddLoanSuccess,
        updateAddLoanFailure,
        // loan data
        getAddLoanSuccess,
        getAddLoanList,
        getAddLoanFailure,
        // getContraSuccess, getContraList, getContraFailure,
        // error
        errorMessage,
    } = appSelector((state) => ({
        //loan data
        getAddLoanSuccess: state.addLoanReducer.getAddLoanSuccess,
        getAddLoanList: state.addLoanReducer.getAddLoanList,
        getAddLoanFailure: state.addLoanReducer.getAddLoanFailure,

        // getContraSuccess: state.contraReducer.getContraSuccess,
        // getContraList: state.contraReducer.getContraList,
        // getContraFailure: state.contraReducer.getContraFailure,

        //create loan data
        createAddLoanSuccess: state.addLoanReducer.createAddLoanSuccess,
        createAddLoanFailure: state.addLoanReducer.createAddLoanFailure,
        //update loan data
        updateAddLoanSuccess: state.addLoanReducer.updateAddLoanSuccess,
        updateAddLoanFailure: state.addLoanReducer.updateAddLoanFailure,

        errorMessage: state.addLoanReducer.errorMessage,
    }));

    const columns = [
        {
            Header: 'S.No',
            accessor: 'id',
            Cell: (row) => <div>{row?.row?.index + 1}</div>,
        },
        {
            Header: 'Staff',
            accessor: 'staffName',
            Cell: ({ row }) => (
                <div className="inbox-item-img" style={{ display: 'flex', alignItems: 'center' }}>
                    <img
                        src={row?.original?.staffProfile ? `${baseURL}${row?.original.staffProfile}` : noProfile}
                        alt="staffProfile"
                        className="rounded-circle"
                        crossOrigin="anonymous"
                        onError={(e) => {
                            e.target.onerror = null;
                            e.target.src = noProfile;
                        }}
                        style={{ width: "40px", height: "40px", objectFit: "cover", marginRight: "10px" }}
                    />
                    <div>
                        <div style={{ fontSize: '15px', fontWeight: '600' }}>
                            {row?.original?.staffName}
                        </div>
                        <div style={{ fontSize: '12px', color: '#888' }}>
                            {row?.original?.staffCode}
                        </div>
                    </div>
                </div>
            )
        },
        {
            Header: 'Loan No',
            accessor: 'loanNo',
            sort: true,
        },
        {
            Header: 'Loan Amount',
            accessor: 'loanAmount',
            sort: true,
            Cell: ({ row }) => {
                const loanAmount = row.original?.loanAmount || 0;
                return (
                    <span>
                        {/* 1 - requested 2-approved 3-cancelled 4-disbursed */}
                        {`₹ ${loanAmount}`}
                    </span>
                );
            },
        },
        {
            Header: 'Loan Type',
            accessor: 'disbursedTypeName',
        },
        {
            Header: 'Actions',
            accessor: 'actions',
            Cell: ({ row }) => {
                return (
                    <div>
                        {/* pdf */}
                        {(roleIdforRole == 1 || _.includes(accessIds, '4')) && row?.original?.loanStatusId !== 30 && <span
                            className="text-warning  me-2 cursor-pointer"
                            onClick={() => {
                                navigate('/loan/pdf', {
                                    state: { loanDetails: row.original, isLoanUrl: true, loc: location.pathname },
                                });
                            }}>
                            <i className={'fas fa-calculator'}></i>
                        </span>}
                        {/* edit */}
                        {(roleIdforRole == 1 || _.includes(accessIds, '2')) && row?.original?.loanStatusId === 28 && (
                            <span
                                className="text-success  me-2 cursor-pointer"
                                onClick={() => {
                                    navigate('/loan/addloan', {
                                        state: { loanDataEdit: row.original, isUpdate: true, loc: location.pathname },
                                    });
                                }}>
                                <i className={'fe-edit-1'}></i>
                            </span>
                        )}
                        {/* status */}
                        {/* Request or to be approval */}
                        {(roleIdforRole == 1 || _.includes(accessIds, '2')) && row?.original?.loanStatusId === 28 && (
                            <span
                                className="text-primary  me-2 cursor-pointer"
                                onClick={() => {
                                    showLoanDetailsModal(row?.original, 29, false);
                                    StatusName = 'Approval';
                                }}>
                                <i className={'fas fa-solid fa-bell'}></i>
                            </span>
                        )}
                        {/* Disbursed */}
                        {(roleIdforRole == 1 || _.includes(accessIds, '2')) && row?.original?.loanStatusId === 29 && (
                            <span
                                className="text-success  me-2 cursor-pointer"
                                onClick={() => {
                                    showLoanDetailsModal(row?.original, 55, false);
                                    StatusName = 'Disbursed';
                                }}>
                                <i className={'fas fa-check-circle'}></i>
                            </span>
                        )}
                        {/* Approval */}
                        {/* {row?.original?.loanStatusId === 55 && (
                            <span className="text-success  me-2 cursor-pointer">
                                <i className={'fas fa-money-bill-1'}></i>
                            </span>
                        )} */}
                        {/* Cancelled */}
                        {(roleIdforRole == 1 || _.includes(accessIds, '2')) && (row?.original?.loanStatusId === 28 || row?.original?.loanStatusId === 29) && (
                            <span
                                className="text-danger  me-2 cursor-pointer"
                                onClick={() => {
                                    showLoanDetailsModal(row?.original, 30, true)
                                    StatusName = 'Cancelled';
                                }}>
                                <i className={'fas fa-power-off'}></i>
                            </span>
                        )}
                        {/* {row?.original?.loanStatusId === 30 && (
                            <span
                                className="text-danger  me-2 cursor-pointer"
                                onClick={() => {
                                    showConfirmationDialog(
                                        'You want to Retrive this loan Applicantion',
                                        () => onChangeStatus(row.original, 1),
                                        'Yes'
                                    );
                                    StatusName = 'Retrive';
                                }}>
                                <i className={'fas fa-recycle'}></i>
                            </span>
                        )} */}
                    </div>
                );
            },
        },
    ];

    const [currentDate, setCurrentDate] = useState({
        disbursedDate: today,
        cancelledReason: '',
    });
    const [optionListState, setOptionListState] = useState({
        contraList: []
    })
    const [modal, setModal] = useState(false);
    const [errors, setErrors] = useState([]);
    const [formData, setFormData] = useState(disbursedDateFormContainer);
    const [isLoading, setIsLoading] = useState(false);
    const [cancelModal, setCancelModal] = useState(false);
    const [parentList, setParentList] = useState([]);
    const [selectedItem, setSelectedItem] = useState([]);
    const [statusItem, setStatusdItem] = useState({});
    const errorHandle = useRef();

    const callDispatchStatus = () => {
        const req = {};
        const pathName = location.pathname.split('/')[2];
        switch (pathName) {
            case 'request':
                req.loanStatusId = 28;
                break;
            case 'approved':
                req.loanStatusId = 29;
                break;
            case 'disbursed':
                req.loanStatusId = 55;
                break;
            case 'cancelled':
                req.loanStatusId = 30;
                break;
            default:
                req.loanStatusId = '';
                break;
        }
        dispatch(getAddLoanRequest(req));
    };

    //Create update addLoan dispatch
    useEffect(() => {
        if (loanData && isCreated) {
            dispatch(createAddLoanRequest(loanData));
        } else if (loanData && isCreated === false) {
            dispatch(updateAddLoanRequest(loanData, loanData.loanId));
        }
        setIsLoading(true);
        callDispatchStatus();
        navigate(location.pathname, { state: { loanData: false, isCreated: false } });
    }, [loanData, isCreated]);

    // Add Loan
    useEffect(() => {
        if (getAddLoanSuccess) {
            setIsLoading(false);
            setParentList(getAddLoanList);
            dispatch(resetGetAddLoan());
        } else if (getAddLoanFailure) {
            setIsLoading(false);
            setParentList({});
            dispatch(resetGetAddLoan());
        }
    }, [getAddLoanSuccess, getAddLoanFailure]);


    // Update Loan
    useEffect(() => {
        if (updateAddLoanSuccess) {
            callDispatchStatus();
            showMessage('success', `Updated Successfully`);
            dispatch(resetUpdateAddLoan());
        } else if (updateAddLoanFailure) {
            showMessage('warning', errorMessage);
            dispatch(resetUpdateAddLoan());
        }
    }, [updateAddLoanSuccess, updateAddLoanFailure]);

    // useEffect(() => {
    //     if (getContraSuccess) {
    //         setOptionListState({
    //             ...optionListState,
    //             contraList: getContraList,
    //         });
    //         // dispatch(resetGetContra());
    //     } else if (getContraFailure) {
    //         setOptionListState({
    //             ...optionListState,
    //             contraList: [],
    //         });
    //         // dispatch(resetGetContra());
    //     }
    // }, [getContraSuccess, getContraFailure]);

    useEffect(() => {
        if (!modal) {
            setCancelModal(false);
            setCurrentDate({
                disbursedDate: today,
                cancelledReason: '',
            });
            setSelectedItem([]);
            setStatusdItem({});
            setFormData(disbursedDateFormContainer);
        }
    }, [modal])

    const handleValidation = () => {
        errorHandle.current.validateFormFields();
    };

    const showLoanDetailsModal = async (data, statusId, isCancel = false) => {
        let emiAmount = emiCalculation(
            parseInt(data?.loanAmount || 0),
            parseInt(data?.interestRate || 0),
            parseFloat(data?.tenurePeriod || 0) / 12
        );
        const loanInfo = {
            "Loan No": data?.loanNo,
            "Loan Date": moment(data?.loanDate).format('DD-MM-YYYY'),
            "Process Fees": `Rs. ${numberWithCommas(data?.processFees)}`,
            "Loan Amount": `Rs. ${numberWithCommas(data?.loanAmount)}`,
            "Monthly EMI": `Rs. ${numberWithCommas(Math.round(emiAmount))}`,
            "Interest Rate": `${data?.interestRate} %`,
            "Disbursed Method": data?.disbursedTypeName,
            "Staff Code": data?.staffCode,
            "Staff Name": data?.staffName,
            "Department": data?.departmentName,
            "Address": data?.address,
        }

        setStatusdItem({
            staffLoanId: data?.staffLoanId,
            statusId: statusId,
        });

        const loanInforArrayObject = Object.entries(loanInfo);

        setSelectedItem(loanInforArrayObject);
        if (isCancel) {
            setCancelModal(true);
        }
        setModal(true);
    }

    const onChangeStatus = async (data, statusId) => {
        let req = {
            loanStatusId: statusId,
            staffLoanId: data?.staffLoanId,
        };

        // request to approval or clearance
        if (statusId === 29) {
            req.approvedBy = roleIdforRole;
            req.approvedDate = moment(new Date()).format('YYYY-MM-DD');
        }

        //approval to Cancelation
        if (statusId == 30) {
            req.cancelledBy = roleIdforRole;
            req.cancelledDate = moment(new Date()).format('YYYY-MM-DD');
            req.cancelledReason = currentDate.cancelledReason;
        }

        // approval to disbursed
        if (statusId == 55) {
            req.disbursed_by = roleIdforRole;
            req.disbursedDate = moment(new Date()).format('YYYY-MM-DD');
        }

        setModal(false);
        dispatch(updateAddLoanRequest(req, data.staffLoanId));
        setCurrentDate({
            disbursedDate: today,
            cancelledReason: '',
        });
    };

    const onHandleContra = (data, name, uniqueKey) => {
        const totalval = data.contraId != 1 ? currentDate?.loanDetails[0]?.loanAmount : 0;
        setCurrentDate({
            ...currentDate,
            [name]: data[uniqueKey],
            contraTotalAmount: totalval,
            transactionId: "",
            twoThousCount: 0,
            fiveHundCount: 0,
            hundCount: 0,
            fivtyCount: 0,
            twentyCount: 0,
            tenCount: 0,
            fiveCoinCount: 0,
            twoCoinCount: 0,
            oneCoinCount: 0,
        })
        let formArr = disbursedDateFormContainer[0].formFields
        let filteredArr = _.filter(formArr, (value, index) => index === 0 || index === 1);
        if (data.contraId != 1) {
            let addTransctionField = {
                'label': "Transaction Id",
                'name': "transactionId",
                'inputType': "text",
                'placeholder': "Enter Transaction ID",
                'require': true,
            }
            filteredArr.push(addTransctionField);
            let tempArr = [
                {
                    formFields: []
                }
            ];
            tempArr[0].formFields = filteredArr
            setFormData(tempArr);
        } else {
            let tempArr = [
                {
                    formFields: []
                }
            ];
            tempArr[0].formFields = _.concat(filteredArr, cashHistoryFormContainer)
            setFormData(tempArr);
        }
    }

    const onHandleCashAmount = (event, name) => {
        let total = 0
        let enterVal = event.target.value

        const twoThousand = name === 'twoThousCount' ? enterVal * 2000 : currentDate.twoThousCount * 2000;
        const fiveHund = name === 'fiveHundCount' ? enterVal * 500 : currentDate.fiveHundCount * 500;
        const hund = name === 'hundCount' ? enterVal * 100 : currentDate.hundCount * 100;
        const fivty = name === 'fivtyCount' ? enterVal * 50 : currentDate.fivtyCount * 50;
        const twenty = name === 'twentyCount' ? enterVal * 20 : currentDate.twentyCount * 20;
        const ten = name === 'tenCount' ? enterVal * 10 : currentDate.tenCount * 10;
        const fiveCoin = name === 'fiveCoinCount' ? enterVal * 5 : currentDate.fiveCoinCount * 5;
        const twoCoin = name === 'twoCoinCount' ? enterVal * 2 : currentDate.twoCoinCount * 2;
        const oneCoin = name === 'oneCoinCount' ? enterVal * 1 : currentDate.oneCoinCount * 1;
        total = parseInt(twoThousand) + parseInt(fiveHund) + parseInt(hund) + parseInt(fivty) + parseInt(twenty) + parseInt(ten) + parseInt(fiveCoin) + parseInt(twoCoin) + parseInt(oneCoin)

        if (total > currentDate?.loanDetails[0]?.loanAmount) {
            showMessage('warning', 'Its Crossing Your Loan Limit...!')
            return false;
        }
        setCurrentDate({
            ...currentDate,
            [name]: enterVal,
            contraTotalAmount: total
        })
    }

    return (
        <React.Fragment>
            <NotificationContainer />
            {isLoading ? (
                <div className="bg-light opacity-0.25">
                    <div className="d-flex justify-content-center m-5">
                        <Spinner className="mt-5 mb-5" animation="border" />
                    </div>
                </div>
            ) : (
                <Table
                    columns={location.pathname == '/loan/cancelled' ? columns.slice(0, columns.length - 1) : columns}
                    toggle={false}
                    Title={`${capitalizeFirstLetter(location.pathname.split('/')[2])} Loan List`}
                    data={parentList || []}
                    pageSize={10}
                // filterTbl={false}
                // filterFormContainer={districtFormContainer}
                // filterColNo={1}
                />
            )}

            <ModelViewBox
                modal={modal}
                setModel={setModal}
                modelHeader={`${cancelModal ? 'Loan Cancellation' : statusItem.statusId == 29 ? 'Approval' : 'Disbursed'}  ${cancelModal ? '' : 'Loan Details'}`}
                modelSize={'lg'}
                btnName={statusItem?.statusId == 29 ? 'Approval' : cancelModal ? 'Cancellled' : 'Disbursed'}
                btnColor={"success"}
                cancelBtn={true}
                modelHead={true}
                handleSubmit={
                    statusItem.statusId === 30 ? handleValidation :
                        () =>
                            showConfirmationDialog(
                                `You want to ${statusItem.statusId == 29 ? 'Approval' : 'Disbursed'} this loan Applicantion`,
                                () => onChangeStatus(statusItem, statusItem.statusId),
                                'Yes',
                                `${statusItem.statusId == 29 ? 'Approval' : 'Disbursed'}`,
                                `${statusItem.statusId == 29 ? 'Approval' : 'Disbursed'} Successfully`
                            )
                }>
                <div style={{ marginBottom: '20px' }}>
                    <Row style={{ marginBottom: '20px' }}>
                        <Col>
                            <CompanyDetails fontSize="12px" imgSize="200px" classStyle="d-flex justify-content-center flex-column align-items-center" />
                        </Col>
                    </Row>
                    {
                        !cancelModal &&
                        (selectedItem || []).map((Item, i) => {
                            const [Key, Value] = Item;
                            return (
                                <Row key={i} style={{ display: 'flex', justifyContent: 'center', marginBottom: '5px' }}>
                                    <Col md={5}>
                                        <h5 style={{ margin: '0px' }}> {Key}</h5>
                                    </Col>
                                    <Col md={1}>{':'}</Col>

                                    <Col md={5}>
                                        <h5 style={{ margin: '0px' }}> {Value}</h5>
                                    </Col>
                                </Row>
                            )
                        })
                    }

                    <div>
                        {(cancelModal) && (
                            <Row style={{ display: 'flex', justifyContent: 'center', marginBottom: '5px' }}>
                                <Col md={12}>
                                    <FormLayout
                                        dynamicForm={cancelModal ? callcelledFormContainer : formData}
                                        noOfColumns={1}
                                        state={currentDate}
                                        setState={setCurrentDate}
                                        ref={errorHandle}
                                        errors={errors}
                                        setErrors={setErrors}
                                        handleSubmit={
                                            () => {
                                                showConfirmationDialog(
                                                    `You want to ${cancelModal ? 'Cancelled' : 'Disbursed'} this loan Applicantion`,
                                                    () => onChangeStatus(statusItem, statusItem.statusId),
                                                    'Yes',
                                                    `${cancelModal ? 'Cancelled' : 'Disbursed'}`,
                                                    `${cancelModal ? 'Cancelled' : 'Disbursed'} Successfully`
                                                )
                                            }
                                        }
                                        optionListState={optionListState}
                                        onChangeCallBack={{ onHandleContra: onHandleContra, onHandleCashAmount: onHandleCashAmount }}
                                    />
                                </Col>
                            </Row>
                        )}
                    </div>
                </div>
            </ModelViewBox>
        </React.Fragment>
    );
}

export default Index;
