import React, { useEffect, useState } from 'react'
import k3Logo from '../../assets/images/K3_Logo-removebg.png';
import { getSettingsRequest, resetGetSettings } from '../../redux/actions';
import { useRedux } from '../../hooks';
import { baseURL } from '../../api/ApiConfig';

function CompanyDetails(props) {
    const { fontSize, imgSize, classStyle, imgOnly, borderBottom = true, styleObj = {
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        textAlign: 'center',
        width: '100%',
        wordBreak: 'break-word',
    } } = props;



    const { dispatch, appSelector } = useRedux();

    const { getSettingsSuccess, getSettingsList, getSettingsFailure,
    } = appSelector((state) => ({
        getSettingsSuccess: state.settingsReducer.getSettingsSuccess,
        getSettingsList: state.settingsReducer.getSettingsList,
        getSettingsFailure: state.settingsReducer.getSettingsFailure,
        errorMessage: state.settingsReducer.errorMessage,
    }));


    const [companyInfo, setCompanyInfo] = useState({});

    useEffect(() => {
        dispatch(getSettingsRequest());
    }, []);

    useEffect(() => {
        if (getSettingsSuccess) {
            setCompanyInfo({
                companyName: getSettingsList[0].companyName || "",
                companyMobile: getSettingsList[0].companyMobile || "",
                companyAltMobile: getSettingsList[0].companyAltMobile || "",
                companyMail: getSettingsList[0].companyMail || "",
                companyAddress: getSettingsList[0].companyAddress || "",
                companyState: getSettingsList[0].companyState || "",
                companyDistrict: getSettingsList[0].companyDistrict || "",
                companyPincode: getSettingsList[0].companyPincode || "",
                companyGstNo: getSettingsList[0].companyGstNo || "",
                companyLogo: getSettingsList[0].companyLogo || "",
                logoPreview: `${baseURL}${getSettingsList[0].companyLogo}` || "",
                companyDetails: `${getSettingsList[0].companyAddress}, ${getSettingsList[0].companyDistrict}, ${getSettingsList[0].companyState}\n - ${getSettingsList[0].companyPincode}`
            });
            dispatch(resetGetSettings())
        } else if (getSettingsFailure) {
            dispatch(resetGetSettings())
        }
    }, [getSettingsSuccess, getSettingsFailure]);

    return (
        <div
            style={styleObj}
        >
            {imgOnly ? (
                <h3 style={{ marginBottom: 10 }}>
                    <img
                        src={companyInfo?.logoPreview}
                        alt="k3Logo"
                        style={{
                            width: imgSize || '120px',
                            maxWidth: '100%',
                            height: 'auto',
                        }}
                        crossOrigin="anonymous"
                    />
                </h3>
            ) : (
                <>
                    <h3 style={{ marginBottom: 10 }}>
                        <img
                            src={companyInfo?.logoPreview}
                            alt="k3Logo"
                            style={{
                                width: imgSize || '120px',
                                maxWidth: '100%',
                                height: 'auto',
                            }}
                            crossOrigin="anonymous"
                        />
                    </h3>

                    {companyInfo?.companyDetails && (
                        <div style={{ fontSize: fontSize || 14, marginBottom: 5 }}>
                            <b>
                                <i className="fe-map-pin" style={{ color: 'red', marginRight: 5 }}></i>
                                {companyInfo.companyDetails}
                            </b>
                        </div>
                    )}

                    <div style={{ fontSize: fontSize || 14, display: 'flex', flexWrap: 'wrap', justifyContent: 'center', gap: 8 }}>
                        {companyInfo?.companyMail && (
                            <span>
                                <b>
                                    <i className="fe-mail" style={{ color: 'orange', marginRight: 5 }}></i>
                                    {companyInfo.companyMail}
                                </b>
                            </span>
                        )}
                        {companyInfo?.companyMobile && (
                            <span>
                                <b>
                                    <i className="fe-phone" style={{ color: 'blue', marginRight: 5 }}></i>
                                    {companyInfo.companyMobile}
                                </b>
                            </span>
                        )}
                        {companyInfo?.companyGstNo && (
                            <span>
                                <b>
                                    <i className="fe-file-text" style={{ color: 'mediumseagreen', marginRight: 5 }}></i>
                                    {companyInfo.companyGstNo}
                                </b>
                            </span>
                        )}
                    </div>

                    {borderBottom && (
                        <div
                            style={{
                                marginTop: 20,
                                borderBottom: '1px solid #00000026',
                                width: '100%',
                            }}
                        />
                    )}
                </>
            )}
        </div>

    )
}

export default CompanyDetails